#define CHECK(expression) check((expression), #expression, __LINE__)

static uint32_t color(uint8_t red, uint8_t green, uint8_t blue, uint8_t white) {
  return (uint32_t(white) << 24) | (uint32_t(red) << 16) | (uint32_t(green) << 8) | blue;
}

static bool testGpio(int dataGpio) {
  return dataGpio == 3 || dataGpio == 4;
}

constexpr uint8_t TYPE_WS2812_RGB = 22;
constexpr uint8_t TYPE_WS2811_400KHZ = 24;
constexpr uint8_t TYPE_UNSUPPORTED_RGBW = 30;

static bool supportedType(uint8_t type) {
  return type == TYPE_WS2812_RGB || type == TYPE_WS2811_400KHZ;
}

// Models only type gating and independent output routing; it does not emulate a WLED driver.
static uint32_t routeColor(uint8_t type, uint8_t dataGpio, uint32_t source, uint32_t state) {
  return supportedType(type) ? BusRgbCalibration::apply(source, state, dataGpio) : source;
}

void testPacking() {
  const uint32_t state = BusRgbCalibration::pack(126, true, 0, 150, 200);
  CHECK(BusRgbCalibration::gpio(state) == 126);
  CHECK(BusRgbCalibration::enabled(state));
  CHECK(BusRgbCalibration::red(state) == 0);
  CHECK(BusRgbCalibration::green(state) == 150);
  CHECK(BusRgbCalibration::blue(state) == 200);
  CHECK(BusRgbCalibration::gpio(BusRgbCalibration::DEFAULT_STATE) == -1);
  CHECK(!BusRgbCalibration::enabled(BusRgbCalibration::DEFAULT_STATE));
  CHECK(BusRgbCalibration::DEFAULT_STATE == BusRgbCalibration::pack(-1, false, 100, 100, 100));
  CHECK(BusRgbCalibration::valid(-1, 0, 0, 0));
  CHECK(BusRgbCalibration::valid(126, 200, 200, 200));
  CHECK(!BusRgbCalibration::valid(-2, 100, 100, 100));
  CHECK(!BusRgbCalibration::valid(127, 100, 100, 100));
  CHECK(!BusRgbCalibration::valid(3, -1, 100, 100));
  CHECK(!BusRgbCalibration::valid(3, 100, 201, 100));
}

void testScaling() {
  CHECK(BusRgbCalibration::scale(0, 0) == 0);
  CHECK(BusRgbCalibration::scale(1, 50) == 1);
  CHECK(BusRgbCalibration::scale(1, 100) == 1);
  CHECK(BusRgbCalibration::scale(1, 150) == 2);
  CHECK(BusRgbCalibration::scale(3, 50) == 2);
  CHECK(BusRgbCalibration::scale(200, 150) == 255);
  CHECK(BusRgbCalibration::scale(255, 200) == 255);

  // Exhaust all accepted gains with an independent floating-point arithmetic oracle.
  for (unsigned gain = 0; gain <= 200; gain++) {
    const uint32_t state = BusRgbCalibration::pack(3, true, gain, gain, gain);
    for (unsigned channel = 0; channel <= 255; channel++) {
      const uint32_t source = color(uint8_t(channel), uint8_t(channel), uint8_t(channel), 0xA5);
      const uint32_t result = BusRgbCalibration::apply(source, state, 3);
      const double scaled = floor(double(channel) * gain / 100.0 + 0.5);
      const uint8_t expected = scaled > 255.0 ? 255 : uint8_t(scaled);
      CHECK((result >> 16 & 0xFFU) == expected);
      CHECK((result >> 8 & 0xFFU) == expected);
      CHECK((result & 0xFFU) == expected);
      CHECK((result >> 24 & 0xFFU) == 0xA5U);
    }
  }
}

void testBypassesAndRouting() {
  const uint32_t source = color(100, 150, 200, 77);
  const uint32_t boosted = BusRgbCalibration::pack(3, true, 150, 50, 200);
  CHECK(BusRgbCalibration::apply(source, BusRgbCalibration::pack(3, false, 150, 50, 200), 3) == source);
  CHECK(BusRgbCalibration::apply(source, BusRgbCalibration::pack(4, true, 150, 50, 200), 3) == source);
  CHECK(BusRgbCalibration::apply(source, BusRgbCalibration::pack(-1, true, 150, 50, 200), 3) == source);
  CHECK(BusRgbCalibration::apply(source, BusRgbCalibration::pack(3, true, 100, 100, 100), 3) == source);
  CHECK(BusRgbCalibration::apply(source, boosted, 3) == color(150, 75, 255, 77));

  CHECK(routeColor(TYPE_WS2812_RGB, 3, source, boosted) == color(150, 75, 255, 77));
  CHECK(routeColor(TYPE_WS2811_400KHZ, 3, source, boosted) == color(150, 75, 255, 77));
  CHECK(routeColor(TYPE_UNSUPPORTED_RGBW, 3, source, boosted) == source);
  CHECK(routeColor(TYPE_WS2812_RGB, 4, source, boosted) == source);

  const uint32_t selectedThree = BusRgbCalibration::pack(3, true, 50, 150, 200);
  const uint32_t selectedFour = BusRgbCalibration::pack(4, true, 200, 50, 150);
  CHECK(routeColor(TYPE_WS2812_RGB, 3, source, selectedThree) == color(50, 225, 255, 77));
  CHECK(routeColor(TYPE_WS2812_RGB, 4, source, selectedThree) == source);
  CHECK(routeColor(TYPE_WS2812_RGB, 3, source, selectedFour) == source);
  CHECK(routeColor(TYPE_WS2812_RGB, 4, source, selectedFour) == color(200, 75, 255, 77));

  const uint32_t first = routeColor(TYPE_WS2812_RGB, 3, source, boosted);
  const uint32_t second = routeColor(TYPE_WS2812_RGB, 3, source, boosted);
  CHECK(first == second);
}

