    top[RgbCalibrationConfig::ENABLED] = true;
    top[RgbCalibrationConfig::OUTPUT_GPIO] = -1;
    top[RgbCalibrationConfig::RED_GAIN] = 50;
    RgbCalibrationConfig::ReadResult partial = RgbCalibrationConfig::read(root, retained, testGpio);
    CHECK(!partial.complete);
    CHECK(BusRgbCalibration::enabled(partial.state));
