    JsonObject top = root.createNestedObject(RgbCalibrationConfig::NAME);
    top[RgbCalibrationConfig::ENABLED] = false;
    top[RgbCalibrationConfig::OUTPUT_GPIO] = 126;
    top[RgbCalibrationConfig::RED_GAIN] = std::numeric_limits<JsonFloat>::quiet_NaN();
    top[RgbCalibrationConfig::GREEN_GAIN] = 100;
    top[RgbCalibrationConfig::BLUE_GAIN] = 100;
    RgbCalibrationConfig::ReadResult invalidGpio = RgbCalibrationConfig::read(root, defaults, testGpio);
    CHECK(!invalidGpio.complete);
    CHECK(BusRgbCalibration::gpio(invalidGpio.state) == 3);
    CHECK(BusRgbCalibration::red(invalidGpio.state) == 100);
